versions.variantCss:
.wemd-text-card[data-variant="bytedance-card-standard"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 24px 28px;
  margin: 16px 0;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-text-card[data-variant="bytedance-card-standard"] .wemd-component-body {
  padding: 0;
}
.wemd-text-card[data-variant="bytedance-card-standard"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-text-strong);
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 12px 0;
}
.wemd-text-card[data-variant="bytedance-card-standard"] .wemd-component-body .wemd-child-2,
.wemd-text-card[data-variant="bytedance-card-standard"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-text-normal);
  font-size: 15px;
  line-height: 1.75;
  margin: 0 0 8px 0;
}
